def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The most frequent color is the background.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    def runs_on_edge(edge):
        # Each run is (color, start, end), with end exclusive.
        vals = ([grid[0][c] for c in range(w)] if edge == "top" else
                [grid[h - 1][c] for c in range(w)] if edge == "bottom" else
                [grid[r][0] for r in range(h)] if edge == "left" else
                [grid[r][w - 1] for r in range(h)])
        runs = []
        i = 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            color = vals[i]
            j = i + 1
            while j < len(vals) and vals[j] == color:
                j += 1
            runs.append((color, i, j))
            i = j
        return runs

    # Find a pair of equal-length, same-colored bars on opposite edges.
    candidates = []
    for orientation, edge1, edge2 in (
        ("h", "top", "bottom"),
        ("v", "left", "right")
    ):
        for a in runs_on_edge(edge1):
            for b in runs_on_edge(edge2):
                if a[0] == b[0] and (a[2] - a[1]) == (b[2] - b[1]):
                    bar_color = a[0]
                    seeds = []
                    for r in range(h):
                        for c in range(w):
                            if grid[r][c] != bg and grid[r][c] != bar_color:
                                t = c if orientation == "h" else r
                                if a[1] <= t < a[2] or b[1] <= t < b[2]:
                                    seeds.append((r, c))
                    candidates.append((len(seeds), orientation, a, b, bar_color, seeds))

    if not candidates:
        return out

    _, orientation, a, b, bar_color, seeds = max(candidates, key=lambda x: x[0])
    bar_cells = set()

    def edge_cell(edge, t):
        if edge == "top":
            return (0, t)
        if edge == "bottom":
            return (h - 1, t)
        if edge == "left":
            return (t, 0)
        return (t, w - 1)

    edge1, edge2 = (("top", "bottom") if orientation == "h" else ("left", "right"))
    for edge, run in ((edge1, a), (edge2, b)):
        for t in range(run[1], run[2]):
            bar_cells.add(edge_cell(edge, t))

    seed_set = set(seeds)

    def paint_line(r, c, dr, dc, color, stop_at_seed=True):
        nr, nc = r + dr, c + dc
        while 0 <= nr < h and 0 <= nc < w:
            if (nr, nc) in bar_cells:
                break
            if grid[nr][nc] != bg and (nr, nc) not in seed_set:
                break
            if (nr, nc) in seed_set and stop_at_seed:
                out[nr][nc] = 4
                break
            out[nr][nc] = color
            nr += dr
            nc += dc

    for r, c in seeds:
        color = grid[r][c]
        out[r][c] = 4

        t = c if orientation == "h" else r
        if a[1] <= t < a[2]:
            source_run, source_edge, other_run, other_edge = a, edge1, b, edge2
        elif b[1] <= t < b[2]:
            source_run, source_edge, other_run, other_edge = b, edge2, a, edge1
        else:
            continue

        # Extend the seed toward the edge bar it aligns with.
        if orientation == "h":
            dr, dc = ((-1, 0) if source_edge == "top" else (1, 0))
        else:
            dr, dc = ((0, -1) if source_edge == "left" else (0, 1))
        paint_line(r, c, dr, dc, color)

        # Replicate that offset on the opposite bar and project across the grid.
        offset = t - source_run[1]
        other_t = other_run[1] + offset
        sr, sc = edge_cell(other_edge, other_t)
        if orientation == "h":
            dr, dc = ((1, 0) if other_edge == "top" else (-1, 0))
        else:
            dr, dc = ((0, 1) if other_edge == "left" else (0, -1))
        paint_line(sr, sc, dr, dc, color)

    return out
